steps.script:
$cid='tr-autoguard-1794486419'
$o=@{command_id=$cid; log_exists=$false; matched_lines=0; started=0; confirmed=0; failed=0; timeout=0; last_result='unobserved'; task_state='unknown'; task_last_result=$null; chrome_pages=$null}
try {
 $p='C:\TTiTTulares\ttendencias-mobile-trigger.log'
 if(Test-Path -LiteralPath $p){
  $o.log_exists=$true
  $rows=@(Get-Content -LiteralPath $p -Tail 850 -ErrorAction Stop|Where-Object { $_.Contains($cid) })
  $o.matched_lines=$rows.Count
  foreach($s in $rows){
   if($s -match 'PROCESS STARTED|LAUNCH STARTED|EDITORIAL TARGET'){$o.started++}
   if($s -match 'CHAT MESSAGE CONFIRMED|LAUNCH CONFIRMED|EJECUCION LANZADA'){$o.confirmed++}
   if($s -match 'LAUNCH FAILED|LAUNCH NOT CONFIRMED|CHAT LAUNCH LOG ERROR'){$o.failed++}
   if($s -match 'TIMEOUT'){$o.timeout++}
  }
  if($o.confirmed -gt 0){$o.last_result='confirmed_send'}
  elseif($o.failed -gt 0){$o.last_result='failed_launch'}
  elseif($o.started -gt 0){$o.last_result='launched_unconfirmed'}
  elseif($o.matched_lines -gt 0){$o.last_result='seen_no_send_evidence'}
 }
 $task=Get-ScheduledTask -TaskName 'TTendencias Local' -ErrorAction SilentlyContinue
 if($task){$o.task_state=[string]$task.State;$t=Get-ScheduledTaskInfo -TaskName 'TTendencias Local' -ErrorAction SilentlyContinue;if($t){$o.task_last_result=$t.LastTaskResult}}
 try{$pages=@(Invoke-RestMethod -Uri 'http://127.0.0.1:9223/json/list' -TimeoutSec 4);$o.chrome_pages=$pages.Count}catch{}
}catch{$o.error_category='LOCAL_DIAGNOSTIC_EXCEPTION'}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
